from pathlib import Path
import json
import argparse
parser=argparse.ArgumentParser(description='Build the self-contained viewer from the graph JSON.')
parser.add_argument('--atlas-dir',type=Path,default=Path(__file__).resolve().parents[1])
BASE=parser.parse_args().atlas_dir
model=json.loads((BASE/'data/dungeon_graph.json').read_text())
html=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>MK163 | Blue Capital Dungeon — Network 002</title>
<style>
:root{font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#172231;background:#f4f6f8}*{box-sizing:border-box}body{margin:0}header{padding:20px 24px 14px;background:white;border-bottom:1px solid #d8e0e7}h1{font-size:26px;line-height:1.2;margin:6px 0}h2{font-size:18px}.eyebrow{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#586a79;font-weight:700}.sub{font-size:13px;color:#536777;margin:6px 0}.controls{display:flex;gap:9px;flex-wrap:wrap;align-items:center;padding:12px 24px;background:#fff;border-bottom:1px solid #d8e0e7}select,input,button{font:inherit;font-size:13px;border:1px solid #bac6d0;background:white;border-radius:5px;padding:8px}button{cursor:pointer}button:hover{background:#edf2f6}input[type=checkbox]{width:15px;height:15px;padding:0;vertical-align:middle}label{font-size:12px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;min-height:650px}#map{width:100%;height:calc(100vh - 205px);min-height:560px;background:#fff;touch-action:none;cursor:grab}#map.dragging{cursor:grabbing}aside{background:#f4f6f8;border-left:1px solid #d8e0e7;padding:20px;overflow:auto;max-height:calc(100vh - 205px)}.badge{display:inline-block;border:1px solid #bec9d2;border-radius:4px;padding:4px 7px;font-size:11px;margin:2px 4px 2px 0;background:#fff}.small{font-size:12px;line-height:1.55;color:#526574}.nodeLabel{font:11px system-ui;paint-order:stroke;stroke:white;stroke-width:3;stroke-linejoin:round;pointer-events:none}.node{cursor:pointer}.node:hover{filter:drop-shadow(0 0 2px #000)}.neighbor{display:inline-block;margin:3px 2px;padding:4px 6px}.grid{stroke:#e2e8ed;stroke-width:.7}.axisLabel{font:10px system-ui;fill:#72808b}table{font-size:12px;width:100%;border-collapse:collapse}td,th{padding:6px 4px;text-align:left;border-bottom:1px solid #d9e0e7}footer{padding:10px 24px;font-size:12px;color:#586a79;background:#fff;border-top:1px solid #d8e0e7}#note{font-size:12px;color:#745b1a}.heading{font-weight:700}.selected{font-weight:800}details{margin-top:16px}.nowrap{white-space:nowrap}@media(max-width:800px){.layout{grid-template-columns:1fr}aside{border-left:none;border-top:1px solid #d8e0e7;max-height:none}#map{height:65vh;min-height:430px}.controls{padding:10px 12px}header{padding:14px 16px}h1{font-size:22px}}
</style></head><body>
<header><div class="eyebrow">MK163 / Book Red / Violet working atlas / Revision 002</div><h1>Blue Capital Dungeon — 340 nodes, 709 passages.</h1><p class="sub">One three-dimensional graph. Shared coordinates and node IDs in every elevation and plan. No Violet stratum.</p></header>
<div class="controls">
<select id="view" aria-label="Map view"><option value="xz">East–west elevation / all strata</option><option value="yz">North–south elevation / all strata</option><option value="3d">Rotating 3D / all strata</option><option value="R">Red / top-down</option><option value="O">Orange / top-down</option><option value="Y">Yellow / top-down</option><option value="G">Green / top-down</option><option value="B">Blue / top-down</option><option value="xy">Top-down / all strata</option></select>
<input id="search" aria-label="Find node" placeholder="Find Y023 or Y-W015" size="18"><button id="find">Find</button><button id="reset">Reset view</button><button id="zin" aria-label="Zoom in">+</button><button id="zout" aria-label="Zoom out">−</button>
<label><input id="labels" type="checkbox" checked> IDs</label><label><input id="arms" type="checkbox" checked> Terminal arms</label><label><input id="shared" type="checkbox"> Common-scale plans</label><label id="rotation">3D rotation <input id="yaw" type="range" min="-180" max="180" value="32" style="width:90px;vertical-align:middle"></label>
</div><div class="layout"><svg id="map" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Interactive numbered dungeon network"></svg><aside><div id="selection"></div><h2>Network structure</h2><div class="badge">340 nodes</div><div class="badge">709 passages</div><div class="badge">370 independent cycles</div><div class="badge">60 stratum crossings</div><div class="badge">32 terminal tips</div><p class="small">Solid lines: principal natural passages. Dashed lines: lateral terminal arms. Dotted gray lines: adjacent-stratum connections. Squares: dead-end tips. Hollow diamonds: nodes in a neighboring stratum.</p><details open><summary class="heading">Authority boundary</summary><p class="small">The depth bands and 3 / 5 / 8 / 11 / 16-mile principal widths are author-selected. This coordinate embedding, north–south extents and exact passages are a working design proposal, not previously established geography.</p><p class="small">A line crossing is not a junction without a shared node ID. A connection is geological topology, not proof that the party can walk it. Equipment, fatigue, accessibility, ecology placement and travel times remain open.</p></details><details><summary class="heading">How to explore</summary><p class="small">Drag to pan. Use the mouse wheel or +/- buttons to zoom. Click a node to see its coordinates, view-order index and all neighbors. Type R1 or R001 to find Red 1. Width aliases such as Y-W015 find the existing node without creating a second identity.</p></details><p id="note"></p></aside></div><footer>Entrance = (0, 0, 0). x east-positive; y north-positive; z depth-positive. Miles. Basemap geometry is fixed; future route conditions belong in a separate overlay. Entire viewer works offline.</footer>
<script>
const MODEL=__MODEL__;
const COLORS={R:'#a8303c',O:'#ba5c16',Y:'#94720c',G:'#22764d',B:'#245b9a'};
const nodes=MODEL.nodes,edges=MODEL.edges,byId=Object.fromEntries(nodes.map(n=>[n.node_id,n]));
const svg=document.getElementById('map'),view=document.getElementById('view');let selected=null,baseBox=null,currentBox=null,drag=null;
const NS='http://www.w3.org/2000/svg';function el(tag,attrs={}){let e=document.createElementNS(NS,tag);for(let k in attrs)e.setAttribute(k,attrs[k]);return e;}
function project(p){const v=view.value,x=p[0],y=p[1],z=p[2];if(v==='xz')return[x,z];if(v==='yz')return[y,z];if(v==='3d'){const a=+document.getElementById('yaw').value*Math.PI/180;return[x*Math.cos(a)-y*Math.sin(a),z*.88+(x*Math.sin(a)+y*Math.cos(a))*.45];}return[x,-y];}
function coord(n){return project([n.x_mi,n.y_mi,n.depth_mi]);}
function visible(){let ns=nodes.filter(n=>document.getElementById('arms').checked||n.network_role==='principal');let isLayer='ROYGB'.includes(view.value)&&view.value.length===1;let ids=new Set(ns.filter(n=>!isLayer||n.code===view.value).map(n=>n.node_id));let es=edges.filter(e=>ids.has(e.source)||ids.has(e.target));if(!document.getElementById('arms').checked)es=es.filter(e=>e.kind!=='lateral_terminal_passage');let extras=new Set(es.flatMap(e=>[e.source,e.target]));return{ns:nodes.filter(n=>extras.has(n.node_id)||ids.has(n.node_id)),es,ids,isLayer};}
function boxset(b){currentBox=b;svg.setAttribute('viewBox',b.join(' '));}
function draw(reset=true){svg.innerHTML='';let {ns,es,ids,isLayer}=visible();let W=1200,H=850;let extent=ns;if(document.getElementById('shared').checked&&isLayer)extent=nodes;let ps=extent.map(coord);let xx=ps.map(p=>p[0]),yy=ps.map(p=>p[1]);let x0=Math.min(...xx),x1=Math.max(...xx),y0=Math.min(...yy),y1=Math.max(...yy);let dx=Math.max(x1-x0,1),dy=Math.max(y1-y0,1);x0-=dx*.07;x1+=dx*.07;y0-=dy*.09;y1+=dy*.09;dx=x1-x0;dy=y1-y0;
 let scale=Math.min((W-90)/dx,(H-80)/dy);if(view.value==='xz'||view.value==='yz')scale=null;
 let sx=scale||((W-90)/dx),sy=scale||((H-80)/dy);let ox=(W-dx*sx)/2,oy=(H-dy*sy)/2;
 const screen=p=>[ox+(p[0]-x0)*sx,oy+(p[1]-y0)*sy];
 const point=n=>screen(coord(n));let neighbors=new Set(selected?[selected,...byId[selected].neighbors.split('|')]:[]);
 let step=dx>18?2:dx>9?1:.5;
 if(view.value!=='3d'){
 for(let t=Math.ceil(x0/step)*step;t<x1;t+=step){let X=screen([t,y0])[0];svg.append(el('line',{x1:X,y1:20,x2:X,y2:H-30,class:'grid'}));let tx=el('text',{x:X+3,y:H-10,class:'axisLabel'});tx.textContent=t.toFixed(step<1?1:0);svg.append(tx);}
 let ystep=dy>12?2:dy>6?1:.5;for(let t=Math.ceil(y0/ystep)*ystep;t<y1;t+=ystep){let Y=screen([x0,t])[1];svg.append(el('line',{x1:20,y1:Y,x2:W-20,y2:Y,class:'grid'}));let tx=el('text',{x:4,y:Y-3,class:'axisLabel'});tx.textContent=(view.value==='xz'||view.value==='yz'?t:-t).toFixed(ystep<1?1:0);svg.append(tx);}}
 if(view.value==='xz'||view.value==='yz'){MODEL.metadata.layers.forEach(l=>{let Y=screen([x0,l.depth_max_mi])[1];svg.append(el('line',{x1:0,y1:Y,x2:W,y2:Y,stroke:COLORS[l.code],'stroke-opacity':.25,'stroke-width':1.2}));let t=el('text',{x:25,y:screen([x0,(l.depth_min_mi+l.depth_max_mi)/2])[1],fill:COLORS[l.code],'font-size':15,'font-weight':700});t.textContent=l.stratum;svg.append(t);});}
 for(let e of es){let inter=e.kind==='inter_stratum_passage',terminal=e.kind==='lateral_terminal_passage';let hot=selected&&(e.source===selected||e.target===selected);let line=el('polyline',{points:e.geometry_xyz_mi.map(p=>screen(project(p)).join(',')).join(' '),fill:'none',stroke:inter?'#8895a3':COLORS[byId[e.source].code],'stroke-width':hot?2.5:.95,'stroke-opacity':selected&&!hot?.16:.7,'stroke-dasharray':inter?'2 4':terminal?'5 4':'none'});let tt=el('title');tt.textContent=`${e.edge_id}: ${e.source} ↔ ${e.target}\n${e.modeled_centerline_mi.toFixed(3)} miles of proposed centerline; traversal OPEN`;line.append(tt);svg.append(line);}
 for(let n of ns){let [x,y]=point(n),ghost=isLayer&&!ids.has(n.node_id),hot=selected===n.node_id,dim=selected&&!neighbors.has(n.node_id);let g=el('g',{'data-id':n.node_id,class:'node',opacity:dim?.25:1});let shape;if(ghost){shape=el('polygon',{points:`${x},${y-4} ${x+4},${y} ${x},${y+4} ${x-4},${y}`,fill:'white',stroke:'#99a5b2'});}else if(n.degree===1){shape=el('rect',{x:x-3.5,y:y-3.5,width:7,height:7,fill:hot?'#172231':'white',stroke:COLORS[n.code]});}else{shape=el('circle',{cx:x,cy:y,r:hot?6:3.4,fill:hot?'#172231':COLORS[n.code],stroke:'white','stroke-width':.7});}g.append(shape);let tt=el('title');tt.textContent=`${n.node_id} / ${n.west_to_east_index}\nx ${n.x_mi.toFixed(3)}, y ${n.y_mi.toFixed(3)}, depth ${n.depth_mi.toFixed(3)} mi`;g.append(tt);g.addEventListener('click',e=>{if(drag&&drag.moved)return;e.stopPropagation();choose(n.node_id);});svg.append(g);
 if(document.getElementById('labels').checked){let t=el('text',{x:x+5,y:y-5,class:'nodeLabel',fill:ghost?'#7c8794':COLORS[n.code],opacity:dim?.25:1,'font-weight':hot?800:500});t.textContent=n.node_id;svg.append(t);}}
 if(reset||!baseBox){baseBox=[0,0,W,H];boxset(baseBox.slice());}else boxset(currentBox);document.getElementById('rotation').style.display=view.value==='3d'?'inline':'none';}
function choose(id){selected=id;let n=byId[id];let d=document.getElementById('selection');d.innerHTML=`<div class="eyebrow">Selected node</div><h2 style="color:${COLORS[n.code]};font-size:28px;margin:7px 0">${id}</h2><table><tr><td>West–east alias</td><td>${n.west_to_east_index}</td></tr><tr><td>Global index</td><td>${n.global_index}</td></tr><tr><td>x / east</td><td>${n.x_mi.toFixed(3)} mi</td></tr><tr><td>y / north</td><td>${n.y_mi.toFixed(3)} mi</td></tr><tr><td>Depth</td><td>${n.depth_mi.toFixed(3)} mi</td></tr><tr><td>Connections</td><td>${n.degree}</td></tr><tr><td>Network role</td><td>${n.network_role.replaceAll('_',' ')}</td></tr></table><p class="small">${n.site_type.replaceAll('_',' ')}. In-world survey status: unassigned.</p><div id="neighbors"></div><hr style="border:0;border-top:1px solid #d8e0e7;margin:20px 0">`;
 n.neighbors.split('|').forEach(k=>{let b=document.createElement('button');b.className='neighbor';b.textContent=k;b.onclick=()=>{if('ROYGB'.includes(view.value)&&view.value.length===1&&byId[k].code!==view.value){view.value=byId[k].code;draw(true);}choose(k);};d.querySelector('#neighbors').append(b);});draw(false);}
function find(){let raw=document.getElementById('search').value.toUpperCase().trim().replaceAll(' ','');let id=raw;let a=raw.match(/^([ROYGB])-?W0*(\d+)$/);if(a){let alias=a[1]+'-W'+a[2].padStart(3,'0');id=nodes.find(n=>n.west_to_east_index===alias)?.node_id;}else{let b=raw.match(/^([ROYGB])0*(\d+)$/);if(b)id=b[1]+b[2].padStart(3,'0');}if(!id||!byId[id]){document.getElementById('note').textContent='No node matches that ID or width index.';return;}document.getElementById('note').textContent='';if('ROYGB'.includes(view.value)&&view.value.length===1&&byId[id].code!==view.value){view.value=byId[id].code;draw(true);}choose(id);}
function zoom(f,cx=.5,cy=.5){let [x,y,w,h]=currentBox;let nw=w*f,nh=h*f;boxset([x+(w-nw)*cx,y+(h-nh)*cy,nw,nh]);}
view.onchange=()=>draw(true);['labels','arms','shared'].forEach(k=>document.getElementById(k).onchange=()=>draw(true));document.getElementById('yaw').oninput=()=>draw(true);document.getElementById('reset').onclick=()=>{selected=null;document.getElementById('selection').innerHTML='<h2>Explore the network</h2><p class="small">Click a node or search an ID to reveal its coordinates and connections.</p>';draw(true);};document.getElementById('find').onclick=find;document.getElementById('search').onkeydown=e=>{if(e.key==='Enter')find();};document.getElementById('zin').onclick=()=>zoom(.75);document.getElementById('zout').onclick=()=>zoom(1.33);
svg.addEventListener('wheel',e=>{e.preventDefault();let r=svg.getBoundingClientRect();zoom(e.deltaY>0?1.12:.89,(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height);},{passive:false});
svg.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,box:currentBox.slice(),moved:false};svg.classList.add('dragging');});svg.addEventListener('pointermove',e=>{if(!drag)return;let r=svg.getBoundingClientRect();let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>4)drag.moved=true;boxset([drag.box[0]-dx/r.width*drag.box[2],drag.box[1]-dy/r.height*drag.box[3],drag.box[2],drag.box[3]]);});window.addEventListener('pointerup',()=>{svg.classList.remove('dragging');setTimeout(()=>{drag=null;},30);});
document.getElementById('reset').click();
</script></body></html>'''
html=html.replace('__MODEL__',json.dumps(model,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'))
(BASE/'DUNGEON_EXPLORER.html').write_text(html,encoding='utf-8')
print('Offline viewer:',BASE/'DUNGEON_EXPLORER.html')
